def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find monochrome 4-connected components.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy in range(max(0, y-1), min(h, y+2)):
                    for xx in range(max(0, x-1), min(w, x+2)):
                        if (yy, xx) == (y, x):
                            continue
                        if (yy, xx) not in seen and grid[yy][xx] == color:
                            seen.add((yy, xx))
                            stack.append((yy, xx))
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            rs = [y for y,x in cells]; cs = [x for y,x in cells]
            box = (min(rs), min(cs), max(rs), max(cs))
            comps.append({'color': color, 'cells': cells, 'box': box})

    # The palette is a horizontal run of solid, 3-cell-high vertical swatches.
    swatches = []
    for comp in comps:
        y0, x0, y1, x1 = comp['box']
        if len(comp['cells']) == 3 and x0 == x1 and y1-y0 == 2:
            swatches.append((x0, y0, y1, comp['color'], comp))
    groups = {}
    for item in swatches:
        groups.setdefault((item[1], item[2]), []).app

